// Reads from the loaded model what the exchange dialogs offer to pick from

// Revit files: the 3D views ACC extracted (published), which are the only views an exchange can be created from.
// Views generated by the extraction itself (e.g., "New Construction", one per phase) are skipped.
export function getPublished3DViews(model) {
    const root = model.getDocumentNode()?.getRootNode();
    if (!root) {
        return [];
    }
    const names = root.search({ type: 'geometry', role: '3d' })
        .filter(node => !node.data.isMasterView)
        .map(node => node.name());
    return [...new Set(names)];
}

export function getLoadedViewName(model) {
    return model.getDocumentNode()?.name() || null;
}

export function findViewNode(model, viewName) {
    const root = model.getDocumentNode()?.getRootNode();
    return root?.search({ type: 'geometry', role: '3d' }).find(node => node.name() === viewName) || null;
}

// Revit models: the viewer's model tree groups elements by category, family and type (the levels AEC Data Model
// filters work on): root > "Walls" > "Basic Wall" > "Generic - 8"" > elements.
// Returns [{ name, families: [{ name, types: [{ name, dbIds }] }] }], sorted by name.
export function getCategoryTree(model) {
    const tree = model.getInstanceTree();
    const byName = (a, b) => a.name.localeCompare(b.name);
    const children = (dbId) => {
        const ids = [];
        tree.enumNodeChildren(dbId, child => { ids.push(child); });
        return ids;
    };
    return children(tree.getRootId()).map(categoryId => ({
        name: tree.getNodeName(categoryId),
        families: children(categoryId).map(familyId => ({
            name: tree.getNodeName(familyId),
            types: children(familyId).map(typeId => ({ name: tree.getNodeName(typeId), dbIds: children(typeId) })).sort(byName)
        })).sort(byName)
    })).filter(category => category.families.length > 0).sort(byName);
}

// Category, family and type of a node picked in the viewer: the first three levels of its path in the model tree.
// Selecting a category or family node itself gives a shorter path.
export function getCategoryPath(model, dbId) {
    const tree = model.getInstanceTree();
    const rootId = tree.getRootId();
    const path = [];
    for (let id = dbId; id !== rootId && id !== undefined && id !== null; id = tree.getNodeParentId(id)) {
        path.unshift(tree.getNodeName(id));
    }
    return path.slice(0, 3);
}

// IFC files: the IFC class and the GlobalId of each element. Their property names depend on the IFC translation
// (e.g., "IfcClass", "Type" or "Category" holding "IfcDoor"; "GLOBALID" or "IfcGUID"), so they're recognized by
// name and by value. Runs in the property database worker (see executeUserFunction): the function can't use
// anything from outside its body.
function collectIfcProperties(pdb) {
    const normalize = (name) => (name || '').replace(/[\s_]/g, '').toLowerCase();
    const CLASS_NAMES = ['ifcclass', 'ifcentity', 'ifctype', 'entity', 'class', 'type', 'category'];
    const GUID_NAMES = ['globalid', 'ifcglobalid', 'ifcguid', 'guid'];
    const classAttributes = new Map(); // attribute ID -> name
    const guidAttributes = new Set();
    pdb.enumAttributes(function (attrId, def) {
        const names = [normalize(def.name), normalize(def.displayName)];
        if (names.some(name => CLASS_NAMES.includes(name))) {
            classAttributes.set(attrId, def.displayName || def.name);
        }
        if (names.some(name => GUID_NAMES.includes(name))) {
            guidAttributes.add(attrId);
        }
    });
    const classesByAttribute = {}; // attribute ID -> { class name -> [dbId] }
    const globalIds = {}; // dbId -> GlobalId
    pdb.enumObjects(function (dbId) {
        pdb.enumObjectProperties(dbId, function (attrId, valId) {
            if (classAttributes.has(attrId)) {
                const value = pdb.getAttrValue(attrId, valId);
                if (typeof value === 'string' && /^ifc[a-z0-9]+$/i.test(value)) {
                    const classes = classesByAttribute[attrId] = classesByAttribute[attrId] || {};
                    (classes[value] = classes[value] || []).push(dbId);
                }
            } else if (guidAttributes.has(attrId)) {
                const value = pdb.getAttrValue(attrId, valId);
                // IFC GlobalIds are 22 characters long (base64 with an IFC-specific alphabet)
                if (typeof value === 'string' && /^[0-9A-Za-z_$]{22}$/.test(value)) {
                    globalIds[dbId] = value;
                }
            }
        });
    });
    // The property naming the IFC class of the most elements
    let best = null;
    for (const attrId of Object.keys(classesByAttribute)) {
        const count = Object.values(classesByAttribute[attrId]).reduce((sum, ids) => sum + ids.length, 0);
        if (!best || count > best.count) {
            best = { attrId, count };
        }
    }
    return {
        classProperty: best ? classAttributes.get(Number(best.attrId)) : null,
        classes: best ? classesByAttribute[best.attrId] : {},
        globalIds
    };
}

// Returns { classProperty, classes: [{ name, dbIds }], globalIds: Map(dbId -> GlobalId) }
export async function getIfcData(model) {
    const result = await model.getPropertyDb().executeUserFunction(collectIfcProperties);
    return {
        classProperty: result.classProperty,
        classes: Object.entries(result.classes).map(([name, dbIds]) => ({ name, dbIds })).sort((a, b) => a.name.localeCompare(b.name)),
        globalIds: new Map(Object.entries(result.globalIds).map(([dbId, guid]) => [Number(dbId), guid]))
    };
}

// GlobalId of a node picked in the viewer: its own, or the one of its closest ancestor that has one
// (picking can select a geometry node below the IFC element)
export function findGlobalId(model, globalIds, dbId) {
    const tree = model.getInstanceTree();
    for (let id = dbId; id !== undefined && id !== null && id !== tree.getRootId(); id = tree.getNodeParentId(id)) {
        if (globalIds.has(id)) {
            return { dbId: id, globalId: globalIds.get(id) };
        }
    }
    return null;
}

// RSQL string literal: single quotes, with quotes and backslashes escaped
function quote(value) {
    return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

// AEC Data Model filter for the checked types: a whole category or family when all its types are checked,
// e.g., (category=='Windows') or (category=='Walls' and family=='Basic Wall')
export function buildAecFilter(categories, checkedTypes) {
    const clauses = [];
    for (const category of categories) {
        const familyStates = category.families.map(family => ({
            family,
            checked: family.types.filter(type => checkedTypes.has(typeKey(category, family, type)))
        }));
        if (familyStates.every(state => state.checked.length === state.family.types.length)) {
            clauses.push(`category==${quote(category.name)}`);
            continue;
        }
        for (const { family, checked } of familyStates) {
            if (checked.length === family.types.length) {
                clauses.push(`category==${quote(category.name)} and family==${quote(family.name)}`);
            } else {
                for (const type of checked) {
                    clauses.push(`category==${quote(category.name)} and family==${quote(family.name)} and type==${quote(type.name)}`);
                }
            }
        }
    }
    return clauses.map(clause => `(${clause})`).join(' or ');
}

export function typeKey(category, family, type) {
    return JSON.stringify([category.name, family.name, type.name]);
}

// IFC filter: only the =in= operator is supported, e.g., ifcClass=in=('IfcDoor','IfcWindow') or ifcGlobalId=in=('2pboVG_iTEAxRAlSBZpuEx')
export function buildIfcFilter(classNames, globalIds) {
    const clauses = [];
    if (classNames.length > 0) {
        clauses.push(`ifcClass=in=(${classNames.map(quote).join(',')})`);
    }
    if (globalIds.length > 0) {
        clauses.push(`ifcGlobalId=in=(${globalIds.map(quote).join(',')})`);
    }
    return clauses.join(' or ');
}
